import React, { useState } from "react";
import "./style.css";
import { Helmet, HelmetProvider } from "react-helmet-async";
import { Container, Row, Col } from "react-bootstrap";
import { Link } from "react-router-dom";
import { meta } from "../../content_option";
import { useLanguage } from "../../i18n/LanguageContext";
import { portfolioProjects } from "../../data/portfolioData";

export const Portfolio = () => {
  const { t, language } = useLanguage();
  const [activeFilter, setActiveFilter] = useState('all');

  const projects = portfolioProjects[language] || portfolioProjects.en;

  const categories = [
    { id: 'all', label: t('portfolio.filters.all') },
    { id: 'ml', label: t('portfolio.filters.ml') },
    { id: 'nlp', label: t('portfolio.filters.nlp') },
    { id: 'cv', label: t('portfolio.filters.cv') },
    { id: 'analytics', label: t('portfolio.filters.analytics') },
    { id: 'automation', label: t('portfolio.filters.automation') },
  ];

  const filteredProjects = activeFilter === 'all'
    ? projects
    : projects.filter(project => project.category === activeFilter);

  const pageTitle = language === 'pt'
    ? "Portfólio de IA | Projetos de Machine Learning & Automação - Tyber.io"
    : "AI Portfolio | Machine Learning & Automation Projects - Tyber.io";

  const pageDescription = language === 'pt'
    ? "Explore 150+ projetos de IA da Tyber.io: machine learning, NLP, visão computacional e automação. Veja como ajudamos empresas a transformar seus negócios com inteligência artificial."
    : "Explore 150+ AI projects by Tyber.io: machine learning, NLP, computer vision, and automation. See how we help businesses transform with artificial intelligence.";

  return (
    <HelmetProvider>
      <section className="portfolio-page" itemScope itemType="https://schema.org/CollectionPage">
        <Helmet>
          <html lang={language === 'pt' ? 'pt-BR' : 'en'} />
          <title>{pageTitle}</title>
          <meta name="description" content={pageDescription} />
          <link rel="canonical" href="https://tyber.io/portfolio" />
          <meta property="og:title" content={pageTitle} />
          <meta property="og:description" content={pageDescription} />
          <meta property="og:url" content="https://tyber.io/portfolio" />
          <meta property="og:type" content="website" />
          <meta name="twitter:title" content={pageTitle} />
          <meta name="twitter:description" content={pageDescription} />
        </Helmet>

        {/* Hero Section */}
        <div className="portfolio-hero">
          <Container>
            <div className="portfolio-hero__badge">
              <span className="badge-dot"></span>
              <span className="badge-text">{t('portfolio.badge')}</span>
            </div>
            <h1 className="portfolio-hero__title gradient-text">
              {t('portfolio.title')}
            </h1>
            <p className="portfolio-hero__subtitle">
              {t('portfolio.subtitle')}
            </p>

            <div className="page-stats-row">
              <div className="page-stat-card">
                <span className="page-stat-card__value">150+</span>
                <span className="page-stat-card__label">{t('portfolio.stats.projects')}</span>
              </div>
              <div className="page-stat-card">
                <span className="page-stat-card__value">50+</span>
                <span className="page-stat-card__label">{t('portfolio.stats.clients')}</span>
              </div>
              <div className="page-stat-card">
                <span className="page-stat-card__value">98%</span>
                <span className="page-stat-card__label">{t('portfolio.stats.successRate')}</span>
              </div>
            </div>
          </Container>
        </div>

        {/* Filters */}
        <Container className="portfolio-filters">
          <div className="filter-buttons">
            {categories.map(category => (
              <button
                key={category.id}
                className={`filter-btn ${activeFilter === category.id ? 'active' : ''}`}
                onClick={() => setActiveFilter(category.id)}
              >
                {category.label}
              </button>
            ))}
          </div>
        </Container>

        {/* Projects Grid */}
        <Container className="portfolio-section">
          <Row>
            {filteredProjects.map((project) => (
              <Col lg={6} key={project.id} className="mb-4">
                <div className="portfolio-card">
                  <div className="portfolio-card__image">
                    <img src={project.image} alt={project.title} />
                    <div className="portfolio-card__overlay">
                      <div className="portfolio-card__tags">
                        {project.tags.map((tag, idx) => (
                          <span key={idx} className="tag">{tag}</span>
                        ))}
                      </div>
                      <Link to={`/portfolio/${project.id}`} className="portfolio-card__cta">
                        {t('portfolio.cta')}
                        <span className="arrow">→</span>
                      </Link>
                    </div>
                  </div>
                  <div className="portfolio-card__content">
                    <h3 className="portfolio-card__title">{project.title}</h3>
                    <p className="portfolio-card__client">{project.client}</p>
                    <p className="portfolio-card__description">{project.description}</p>
                    <div className="portfolio-card__metrics">
                      {project.metrics.map((metric, idx) => (
                        <div key={idx} className="metric">
                          <div className="metric__value">{metric.value}</div>
                          <div className="metric__label">{metric.label}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </Col>
            ))}
          </Row>
        </Container>
      </section>
    </HelmetProvider>
  );
};
